//! CLI tool to check if a binary uses libc.
//!
//! Exit codes:
//!   0 - Binary does NOT use libc
//!   1 - Binary DOES use libc
//!   2 - Error (file not found, parse error, etc.)

use is_libc_used::is_libc_used;
use std::path::Path;
use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();

    let mut verbose = false;
    let mut path: Option<&str> = None;

    for arg in args.iter().skip(1) {
        match arg.as_str() {
            "-v" | "--verbose" => verbose = true,
            "-h" | "--help" => {
                print_usage(&args[0]);
                return ExitCode::from(0);
            }
            s if s.starts_with('-') => {
                eprintln!("Unknown option: {}", s);
                print_usage(&args[0]);
                return ExitCode::from(2);
            }
            s => {
                if path.is_some() {
                    eprintln!("Error: Multiple paths provided");
                    print_usage(&args[0]);
                    return ExitCode::from(2);
                }
                path = Some(s);
            }
        }
    }

    let path = match path {
        Some(p) => p,
        None => {
            eprintln!("Error: No binary path provided, use -h for help");
            return ExitCode::from(2);
        }
    };

    let path = Path::new(path);
